import 'package:cloud_firestore/cloud_firestore.dart';
class HomeConfigService{final _db=FirebaseFirestore.instance;Stream<DocumentSnapshot<Map<String,dynamic>>> watch()=>_db.collection('app_config').doc('home').snapshots();Future<void> save(Map<String,dynamic> data)=>_db.collection('app_config').doc('home').set(data,SetOptions(merge:true));static Map<String,dynamic> defaults={'title':'Flowa','subtitle':'Jual beli lokal, lebih dekat','bannerTitle':'Temukan barang terbaik di sekitarmu','bannerSubtitle':'Jual, beli, dan chat langsung dengan penjual','showCategories':true,'showBanner':true,'showPopular':true,'categories':['Mobil','Motor','Properti','Elektronik','Fashion','Rumah Tangga','Hobi','Lainnya']};}